  chapterId: "ch11-14",
  prompt: 'codes.txt から、"A-" の後に2桁または3桁の数字が続き、そのまま行末になる行を拡張正規表現で検索してください({2,3} を使う)。',
  initialCwd: "/home/study/practice/ch13_regex",
  referenceSolution: 'grep -E "^A-[0-9]{2,3}$" codes.txt',
