    "$2 ~ /Sales/{sum+=$3} は、2列目がSalesという正規表現にマッチする行だけを対象に3列目(給与)をsumへ加算するという条件付きアクションです。END{print sum}で全行処理後にSales部門の給与合計だけが出力されます。",
